INSERT INTO swsi_batch VALUES ('SP104-1-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第80條（緊急保護安置七十二小時、繼續安置以三個月為限），最後修正公布日：第80條 2009-07-08，本題考試日 2015-02-07 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP105-1-09','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第35條（勞工主管機關應推動設立之職業訓練、就業服務機構及庇護工場），最後修正公布日：第35條 2011-06-29，本題考試日 2016-01-30 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP105-2-22','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第5條（身心障礙者定義之八款身體系統構造或功能），最後修正公布日：第5條 2007-07-11，本題考試日 2016-07-23 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP105-2-32','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-07-23。本題考身心障礙者權益保障法第14條（身心障礙證明效期）。考試時規定有效期限最長五年、效期屆滿前九十日內申請重新鑑定及需求評估；2021-01-20 修正增訂無註記有效期間之身心障礙證明，並將屆滿前申請之規定適用於領有記載有效期間證明者，五年、九十日及屆滿六十日前書面通知之規定未變，選項(B)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP106-1-07','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第78條、第79條（緊急保護安置及安置費用由行為人支付），最後修正公布日：第78條 2007-07-11、第79條 2007-07-11，本題考試日 2017-02-18 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP108-1-21','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第23條（醫院出院準備計畫），最後修正公布日：第23條 2011-02-01，本題考試日 2019-01-19 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP108-2-25','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第71條（直轄市、縣（市）主管機關之經費補助項目），最後修正公布日：第71條 2007-07-11，本題考試日 2019-07-27 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（20